235	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
236	            Actor actor = it.next();
237	            actor.act(newActors, environment);
238	            if(!actor.isAlive()) {
239	                it.remove();
240	            }
241	        }
242	        actors.addAll(newActors);
243	        plantGrassInPatches();
244	
245	        view.showStatus(step, environment, field);
246	    }
