248	    /**
249	     * Randomly generate grass in free patches on the field, only if it is raining
250	     */
251	    private void plantGrassInPatches(){
252	        // new grass is randomly added in patches
253	        for(Location location:field.getRandomFreePatches(CREATION_PROBABILITIES.get(Grass.class))){
254	            if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class) && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
255	                Grass grass = new Grass(field, location);
256	                actors.add(grass);
257	            }
258	        }
259	    }
