286	        factories.put(Coyote.class, (loc, sex) -> new Coyote(true, field, loc, sex));
287	        factories.put(Wolf.class,   (loc, sex) -> new Wolf(true, field, loc, sex));
288	        factories.put(Eagle.class,  (loc, sex) -> new Eagle(true, field, loc, sex));
289	        factories.put(Mouse.class,  (loc, sex) -> new Mouse(true, field, loc, sex));
290	        factories.put(Hunter.class, (loc, sex) -> new Hunter(field, loc, environment));
291	
292	        field.clear();
293	        for(int row = 0; row < field.getDepth(); row++) {
294	            for(int col = 0; col < field.getWidth(); col++) {
295	                Location location = new Location(row, col);
296	                Animal.Gender sex = Randomizer.getRandomSex();
297	                for(Map.Entry<Class<?>, BiFunction<Location, Animal.Gender, Actor>> entry : factories.entrySet()) {
298	                    Class<?> cls = entry.getKey();
299	                    if(cls == Hunter.class && HUNTER_COUNT >= HUNTER_LIMIT) continue;
300	                    if(rand.nextDouble() <= CREATION_PROBABILITIES.get(cls)) {
301	                        actors.add(entry.getValue().apply(location, sex));
302	                        if(cls == Hunter.class) HUNTER_COUNT++;
303	                        break;
304	                    }
305	                }
306	                // else leave the location empty
307	            }
308	        }
309	    }
